const checkRoots=async IDS=>{const issues=[],rows=[];let assertions=0;const assert=(ok,message,id)=>{assertions++;if(!ok)issues.push([id,message]);};const cache={};const get=async id=>{if(cache[id])return cache[id];const root=await figma.getNodeByIdAsync(id),entry=registry[id],g=groups.find(g=>g.stage===entry.stage),c=controls(root),rx=cleanRx(root.reactions).find(r=>r.trigger?.type==='AFTER_TIMEOUT'&&Math.abs(r.trigger.timeout-0.001)<0.0000001);return cache[id]={root,entry,g,c,actions:rx?.actions||[]};};const arrive=async(id,s)=>{const d=await get(id);execute(d.actions,s);return d;};const confirm={},cancel={},close={};for(const [theme,id]of Object.entries(dialogs)){const root=await figma.getNodeByIdAsync(id),a=root.children.find(n=>n.name==='Dialog actions');confirm[theme]=click(a.children.find(n=>n.name==='Confirm workspace reset'));cancel[theme]=click(a.children.find(n=>n.name==='Cancel dialog'));const closeNode=root.children.find(n=>n.name==='Dialog header').findAll(n=>'reactions'in n&&n.reactions.some(rx=>(rx.actions||[]).some(a=>a.type==='CLOSE')))[0];close[theme]=closeNode?click(closeNode):[];assert(close[theme].some(a=>a.type==='CLOSE'),'Close dialog action missing',id);const test=newSession();execute(close[theme],test);assert(test.closed&&JSON.stringify(test.values)===JSON.stringify(newSession().values),'Close changed values',id);}
for(const id of IDS){const d=await get(id),{entry,g,c}=d,s=newSession();assert(d.actions.length>0,'root initializer missing',id);assert(c.s.resolvedVariableModes['VariableCollectionId:17:3']===entry.theme,'theme changed',id);assert(entry.transient?c.back.componentProperties.State.value==='Disabled'&&!c.back.componentProperties.State.boundVariables?.value:c.back.componentProperties.State.boundVariables?.value?.id===V['History/back state'],'Back binding or lock',id);assert(entry.transient?c.forward.componentProperties.State.value==='Disabled'&&!c.forward.componentProperties.State.boundVariables?.value:c.forward.componentProperties.State.boundVariables?.value?.id===V['History/forward state'],'Forward binding or lock',id);execute(d.actions,s);assert(value(s,'History/current')===entry.canonical&&value(s,'History/group')===entry.stage,'identity initialization',id);const base=entry.canonical===g.baseKey;assert(value(s,'History/index')===(base||entry.transient?0:1),'initial depth',id);assert(!Object.keys(V).filter(n=>n.startsWith('History/slot ')).some(n=>{const key=value(s,n);return g.items.some(item=>item.key===key&&Object.values(item.dest).some(t=>registry[t].transient));}),'transient snapshot recorded',id);
if(entry.transient){assert(click(c.back).length===0&&click(c.forward).length===0,'transient history pointer action',id);assert(value(s,'History/back state')==='Disabled'&&value(s,'History/forward state')==='Disabled','transient global flags',id);}else if(base){execute(click(c.back),s);assert(s.destinations.length===0,'empty Back navigated',id);execute(click(c.forward),s);assert(s.destinations.length===0,'empty Forward navigated',id);}else{execute(click(c.back),s);const target=s.destinations.at(-1)?.[0];assert(target===g.base[entry.theme]&&value(s,'History/index')===0,'first Back target/theme',id);if(target&&registry[target]){const b=await arrive(target,s);assert(value(s,'History/back state')==='Disabled'&&value(s,'History/forward state')==='Default','base boundary flags',id);s.destinations=[];execute(click(b.c.forward),s);const f=s.destinations.at(-1)?.[0];assert(f===id&&value(s,'History/index')===1,'Forward snapshot/theme',id);if(f)await arrive(f,s);assert(value(s,'History/forward state')==='Disabled','final Forward flag',id);s.destinations=[];execute(click(c.forward),s);assert(s.destinations.length===0,'last Forward navigated',id);}}
if(entry.transient||entry.originalResetDisabled){assert(c.reset.componentProperties.State.value==='Disabled'&&click(c.reset).length===0,'Reset lock bypass',id);}else{const before=JSON.stringify(Object.fromEntries(Object.keys(V).filter(n=>n.startsWith('History/')).map(n=>[n,value(s,n)]))),theme=entry.theme==='17:2'?'Dark':'Light';s.destinations=[];execute(click(c.reset),s);assert(s.destinations.at(-1)?.[0]===dialogs[theme],'Reset dialog theme',id);assert(before===JSON.stringify(Object.fromEntries(Object.keys(V).filter(n=>n.startsWith('History/')).map(n=>[n,value(s,n)]))),'Reset open changed history',id);const vars=JSON.stringify(s.values);execute(cancel[theme],s);assert(vars===JSON.stringify(s.values)&&s.closed,'Cancel changed values or did not close',id);s.destinations=[];execute(confirm[theme],s);assert(s.destinations.at(-1)?.[0]===entry.reset,'Reset neutral/category target',id);assert(value(s,'History/index')===0&&value(s,'History/end')===0&&value(s,'History/back state')==='Disabled'&&value(s,'History/forward state')==='Disabled','Reset did not clear cursor',id);assert(Array.from({length:8},(_,i)=>value(s,'History/slot '+(i+1))).every(v=>v==='')&&value(s,'History/back target')===''&&value(s,'History/forward target')==='','Reset retained snapshots/targets',id);await arrive(entry.reset,s);assert(value(s,'History/index')===0&&value(s,'History/end')===0,'Reset entry recreated detail history',id);}
rows.push([id,entry.transient,entry.originalResetDisabled]);}
return {scope:'Interpretation of actual stored actions with actual destination-root initialization; not browser playback',rootsChecked:IDS.length,assertions,issueCount:issues.length,issues,rows};};
